'use strict';
const $=id=>document.getElementById(id);
const cities={beijing:[39.9042,116.4074,8],shanghai:[31.2304,121.4737,8],nanjing:[32.0603,118.7969,8],guangzhou:[23.1291,113.2644,8],chengdu:[30.5728,104.0668,8],singapore:[1.3521,103.8198,8],sydney:[-33.8688,151.2093,10]};
let result,params,filter='all',selected,visibleLimit=24;
function matches(o){const lim=Number($('maglimit').value)||4;if(o.kind==='star'&&o.mag>lim)return false;const r=display(o),q=$('search').value.trim().toLowerCase();return !q||[o.name,o.group,o.id,o.hip,r.name,r.group,r.alternate,o.international,o.chinese,o.designation].filter(Boolean).join(' ').toLowerCase().includes(q);}

const dateString=(d,offset)=>new Date(+d+offset*3600000).toISOString().slice(0,10);
function clock(d){if(!d)return '无交点';const x=new Date(+d+params.offset*3600000);return (x.toISOString().slice(0,10)>params.date?'次日 ':'')+x.toISOString().slice(11,16);}
const dir=a=>['北','东北','东','东南','南','西南','西','西北'][Math.round(a/45)%8];
const display=o=>Cultures.describe(o,$('culture').value||'modern');
const type=o=>({star:'亮星',planet:'行星',moon:'月球',dso:'深空',cluster:'星团'}[o.kind]);
function renderCards(){const all=result.rows.filter(r=>r.best&&matches(r));const rows=all.filter(r=>filter==='all'||filter==='planet'&&['planet','moon'].includes(r.kind)||filter==='star'&&r.kind==='star'||filter==='deep'&&['dso','cluster'].includes(r.kind));$('count').textContent=rows.length+' 个可选目标';$('more').hidden=rows.length<=visibleLimit;$('cards').replaceChildren();if(!rows.length){$('selectedName').textContent='当前筛选暂无目标';$('selectedTip').textContent='更换目标类型、日期或器材后再试。';$('detailMeta').textContent='';$('chart').innerHTML='';$('compass').innerHTML='';$('cards').innerHTML='<p class="empty">这组条件下没有达到建议高度的目标。可换日期、器材或目标类型。</p>';return;}if(!rows.some(r=>r.id===selected))selected=rows[0].id;for(const raw of rows.slice(0,visibleLimit)){const r=display(raw);const b=document.createElement('button');b.className='card'+(r.id===selected?' selected':'');b.setAttribute('aria-pressed',String(r.id===selected));b.innerHTML=`<span class="cardhead"><b>${r.name}</b><span class="tag">${type(r)} · ${r.group}</span></span><small class="numbers">最佳 ${clock(r.best.t)} · ${dir(r.best.az)} ${r.best.az.toFixed(0)}° · 高度 ${r.best.alt.toFixed(0)}°</small><small>建议窗口 ${clock(r.window[0])}–${clock(r.window[1])}${r.moonPenalty>10?' · 月光干扰':''}</small>`;b.onclick=()=>{selected=r.id;renderCards();};$('cards').append(b);}showDetail(display(rows.find(r=>r.id===selected)));}
function showDetail(r){$('selectedName').textContent=r.name;$('selectedTip').textContent=r.tip+' '+r.cultureNote+(r.alternate?' 对照：'+r.alternate:'');$('detailMeta').textContent=`视星等 ${r.mag.toFixed(1)}　/　最佳高度 ${r.best.alt.toFixed(0)}°${r.moonPenalty>10?'　/　建议寻找更暗的时段':''}`;
const W=560,H=220,x=i=>42+i/144*500,y=a=>180-a/90*150;
let svg='';for(let i=0;i<144;i++)if(result.sun[i]<=-12)svg+=`<rect x="${x(i)}" y="20" width="3.6" height="160" fill="#eac98b" opacity=".07"/>`;
for(const a of[0,20,45,90])svg+=`<line x1="42" x2="542" y1="${y(a)}" y2="${y(a)}" stroke="#66758b" opacity=".4" ${a===20?'stroke-dasharray="5 5"':''}/><text x="4" y="${y(a)+5}" fill="#9eafc5" font-size="13">${a}°</text>`;
for(let i=0;i<=144;i+=36)svg+=`<text x="${x(i)}" y="210" text-anchor="${i===0?'start':i===144?'end':'middle'}" fill="#9eafc5" font-size="13">${clock(result.times[i])}</text>`;
let path='',pen=false;for(let i=0;i<r.samples.length;i++){const a=r.samples[i].alt;if(a<0){pen=false;continue;}path+=(pen?'L':'M')+x(i).toFixed(1)+','+y(a).toFixed(1);pen=true;}svg+=`<path d="${path}" fill="none" stroke="#eac98b" stroke-width="2.5"/>`;$('chart').innerHTML=svg;
const angle=r.best.az*Math.PI/180,cx=140,cy=100,px=cx+65*Math.sin(angle),py=cy-65*Math.cos(angle);$('compass').innerHTML=`<circle cx="140" cy="100" r="66" fill="none" stroke="#405069"/><path d="M140 34V166M74 100H206" stroke="#405069" stroke-dasharray="3 5"/><text x="140" y="22" text-anchor="middle" fill="#9eafc5">北</text><text x="140" y="191" text-anchor="middle" fill="#9eafc5">南</text><text x="224" y="106" fill="#9eafc5">东</text><text x="40" y="106" fill="#9eafc5">西</text><line x1="140" y1="100" x2="${px}" y2="${py}" stroke="#eac98b" stroke-width="2"/><circle cx="${px}" cy="${py}" r="5" fill="#eac98b"/><circle cx="140" cy="100" r="3" fill="#9eafc5"/>`;}
function renderCatalog(){const objects=[Sky.moon,...Sky.planets,...Sky.catalog].filter(matches);$('catalogCount').textContent=objects.length+' 个目标';$('catalogRows').innerHTML=objects.map(o=>{const r=display(o);return `<tr><td>${r.name}</td><td>${r.group}</td><td>${r.alternate||r.id}</td><td>${type(r)}</td></tr>`;}).join('');}
function run(){try{params={date:$('date').value,lat:Number($('lat').value),lon:Number($('lon').value),offset:Number($('offset').value),gear:$('gear').value};result=Sky.calculate(params);$('datemark').textContent=params.date.replaceAll('-',' / ');const darkText=result.dark.length===145?'整段极夜':!result.dark.length?'无天文黑夜':clock(result.dusk)+' — '+clock(result.dawn);$('stats').innerHTML=`<div class="stat"><span>天文黑夜 · 太阳低于 −18°</span><strong>${darkText}</strong></div><div class="stat"><span>当晚 21:00 月面照亮比例</span><strong>${Math.round(result.phase*100)}%</strong></div><div class="stat"><span>时间均按所选 UTC 时差显示</span><strong>UTC${params.offset>=0?'+':''}${params.offset}</strong></div>`;$('status').textContent=`${params.lat.toFixed(3)}°，${params.lon.toFixed(3)}° · 地平线无遮挡假设${!result.dark.length?' · 本夜没有完全黑暗的天文夜，深空观测受限':''}`;const available=result.rows.filter(r=>r.best&&matches(r));if(!available.length){$('selectedName').textContent='本夜暂无推荐';$('selectedTip').textContent='可能处于极昼，或所选条件不适合。试试其他日期。';$('detailMeta').textContent='';$('chart').innerHTML='';$('compass').innerHTML='';}renderCards();renderCatalog();try{localStorage.setItem('nightwatch.preferences',JSON.stringify({...params,city:$('city').value,culture:$('culture').value}));}catch{}}catch(e){$('status').textContent='无法生成：'+e.message;}}
$('culture').onchange=()=>{renderCards();renderCatalog();try{const saved=JSON.parse(localStorage.getItem('nightwatch.preferences'))||{};saved.culture=$('culture').value;localStorage.setItem('nightwatch.preferences',JSON.stringify(saved));}catch{}};
$('more').onclick=()=>{visibleLimit+=24;renderCards();};
for(const id of ['search','maglimit'])$(id).oninput=()=>{visibleLimit=24;renderCards();renderCatalog();};
$('form').onsubmit=e=>{e.preventDefault();run();};$('city').onchange=()=>{const c=cities[$('city').value];if(c){[$('lat').value,$('lon').value,$('offset').value]=c;if($('city').value==='sydney')$('status').textContent='悉尼标准时间 UTC+10，夏令时请改为 UTC+11。';}};for(const id of['lat','lon'])$(id).oninput=()=>{$('city').value='custom';};document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;document.querySelectorAll('[data-filter]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b));});renderCards();});$('red').onclick=()=>{const red=document.body.classList.toggle('red');$('red').setAttribute('aria-pressed',String(red));};$('locate').onclick=()=>{if(!navigator.geolocation){$('status').textContent='浏览器不支持定位，请手动输入经纬度。';return;}$('status').textContent='等待定位授权…';navigator.geolocation.getCurrentPosition(p=>{$('lat').value=p.coords.latitude.toFixed(4);$('lon').value=p.coords.longitude.toFixed(4);$('offset').value=-new Date().getTimezoneOffset()/60;$('city').value='custom';run();},()=>{$('status').textContent='定位不可用或未授权，请选择城市或手动输入。';},{timeout:10000});};
try{const p=JSON.parse(localStorage.getItem('nightwatch.preferences'));if(p){for(const id of['lat','lon','offset','gear','city','culture'])if(p[id]!==undefined)$(id).value=p[id];}}catch{}
$('date').value=dateString(new Date(),Number($('offset').value));run();
